type c = [string, number];
type d = "left" | "right";


interface 可以重复定义相同名字的接口，并且这个接口会在之前的基础上进行合并而不是覆盖，type 定义相同的类型别名会报错

interface IPerson &#123;
  name: string;
&#125;
interface IPerson &#123;
  age: number;
&#125;

const person: IPerson = &#123;
  name: "a",
  age: 1,
&#125;;

type TPerson = &#123;
  // 标识符“TPerson”重复
  name: string;
&#125;;
type TPerson = &#123;
  // 标识符“TPerson”重复
  age: number;
&#125;;

二、接口的使用2.1 接口的继承interface aType &#123;
  name: string;
&#125;

interface bType &#123;
  age: number;
&#125;

// 接口可以继承多个，方便了接口的复用性
interface cType extends aType, bType &#123;
  height?: number;
&#125;

let obj: cType = &#123;
  name: "xujie",
  age: 89,
&#125;;

2.2 可选参数// ? 代表 name 属性是一个可选的参数
interface paramsTs &#123;
  label: string;
  name?: string;
&#125;

2.3 只读属性// readonly 代表属性只能在被初次创建时给一个值，创建完成之后就不能在修改属性的值了
// 只读变量用 const, 只读属性用 readonly
interface Point &#123;
  readonly x: number;
  readonly y: number;
&#125;

2.4 class 实现 interface// 定义一个接口
interface aType &#123;
  content: string;
  say: (content: string) => void;
&#125;

// 实现 Person 父类
class Person &#123;
  content: string;
