TypeScript类型缩小
TS 只有对联合的每个对象都有效的情况下才允许操作

function printId(id: number | string) &#123;
  // 类型“string | number”上不存在属性“toUpperCase”。类型“number”上不存在属性“toUpperCase”。ts(2339)
  console.log(id.toUpperCase());
&#125;


解决方案是使用代码进行类型缩小
当 TypeScript 可以根据代码的结构为某个值推断出更具体的类型时，类型就会发生缩小(将类型精炼为比声明的更具体的类型的过程)。

function printId(id: number | string) &#123;
  if (typeof id === "string") &#123;
    console.log(id.toUpperCase()); // id 的类型被缩小为 string(将鼠标移到变量 id 上可查看)
  &#125; else &#123;
    console.log(id++); // id 的类型被缩小为 number (将鼠标移到变量 id 上可查看)
  &#125;
&#125;

一、类型缩小的方式1.1 typeof 类型保护
typeof 的返回值”string”、”number”、”bigint”、”boolean”、”symbol”、”undefined”、”object”、”function”
在 TypeScript 中，检查 typeof 返回的值是一种类型保护。因为 TypeScript 编码了 typeof 如何对不同的值进行操作，所以它知道它在 JavaScript 中的一些怪癖

function printAll(strs: string | string[] | null) &#123;
  if (typeof strs === "object") &#123;
    for (const s of strs) &#123;
      // “strs”可能为 “null”。
      console.log(s);
    &#125;
  &#125; else if (typeof strs === "string") &#123;
    console.log(strs);
  &#125; else &#123;
    // do nothing
  &#125;
&#125;

1.2 真值缩小
七种 false 的值：false、null、undefined、0、NaN、””、0n(bigint)
在 JS 例如 if() 这样的代码结构中，会自动将条件强制转化为 boolean 类型

function printAll(strs: string | string[] | null) &#123;
  if (strs &amp;&amp; typeof strs === "object") &#123;
    // strs 不再会是 null
    for (const s of strs) &#123;
      console.log(s);
    &#125;
  &#125; else if (typeof strs === "string") &#123;
    console.log(strs);
  &#125; else &#123;
    // do nothing
  &#125;
&#125;

1.3 相等性缩小
TS 还可以使用 switch、&#x3D;&#x3D;&#x3D;、!&#x3D;&#x3D;、&#x3D;&#x3D;、!&#x3D; 等相等性检查来缩小类型

function example(x: string | number, y: string | boolean) &#123;
  if (x === y) &#123;
    // 因为 x === y 所以 x 和 y 的类型也肯定一样，所以一定是 string
    x.toUpperCase(); // (parameter) x: string
    y.toLowerCase(); // (parameter) y: string
  &#125; else &#123;
    console.log(x); // (parameter) x: string | number
    console.log(y); // (parameter) y: string | boolean
  &#125;
&#125;

1.4 in 运算符缩小
prop in object: 指定的属性是否在指定的对象或其原型链中

function move(animal: Fish | Bird | Human) &#123;
  if ("swim" in animal) &#123;
    animal; // (parameter) animal: Fish | Bird
  &#125; else &#123;
    animal; // (parameter) animal: Bird | Human
  &#125;
&#125;

1.5 instanceof 缩小
x instanceof Foo: 检查 x 的原型链是否包含 Foo.prototype

function logValue(x: Date | string) &#123;
  if (x instanceof Date) &#123;
    console.log(x.toUTCString()); // (parameter) x: Date
  &#125; else &#123;
    console.log(x.toUpperCase()); // (parameter) x: string
  &#125;
&#125;

1.6 使用类型谓词
parameterName is Type: is 关键字一般用于函数返回值类型中，判断参数是否属于某一类型，并根据结果返回对应的布尔类型。

// 一、不使用类型谓词
function isString(s: unknown): boolean &#123;
  return typeof s === "string";
&#125;

function ifUpperCase(str: unknown) &#123;
  if (isString(str)) &#123;
    // (parameter) str: unknown
    // 报错:类型“unknown”上不存在属性“toUpperCase”
    str.toUpperCase();
  &#125;
&#125;

// 二、使用类型谓词
function isString(s: unknown): s is string &#123;
  return typeof s === "string";
&#125;

function ifUpperCase(str: unknown) &#123;
  if (isString(str)) &#123;
    str.toUpperCase(); // (parameter) str: string
  &#125;
&#125;

// 三、直接使用 typeof
function ifUpperCase(str: unknown) &#123;
  if (typeof str === "string") &#123;
    str.toUpperCase(); // (parameter) str: string
  &#125;
&#125;


使用类型谓词来判断复杂类型

interface Animal &#123;
  song: () => void;
&#125;

interface Dog extends Animal &#123;
  jump: () => void;
&#125;

interface Cat extends Animal &#123;
  rapper: () => void;
&#125;

function isCat(animal: Animal): animal is Cat &#123;
  return (animal as Cat).rapper !== undefined;
&#125;

function showTime(animal: Cat | Dog) &#123;
  if (isCat(animal)) &#123;
    animal.rapper(); // (parameter) animal: Cat
  &#125; else &#123;
    animal.jump(); // (parameter) animal: Dog
  &#125;
&#125;

const cat: Cat = &#123;
  song: () => &#123;
    console.log("song");
  &#125;,
  rapper: () => &#123;
    console.log("rapper");
  &#125;,
&#125;;

showTime(cat);

1.7 判别联合
当联合中的每个类型都包含具有字面类型的公共属性时。TS 认为这是一个可区分的联合

interface Circle &#123;
  kind: "circle";
  radius: number;
&#125;

interface Square &#123;
  kind: "square";
  sideLength: number;
&#125;

type Shape = Circle | Square;

function getArea(shape: Shape) &#123;
  if (shape.kind === "circle") &#123;
    return Math.PI * shape.radius ** 2; // (parameter) shape: Circle
  &#125; else &#123;
    return shape.sideLength ** 2; // (parameter) shape: Square
  &#125;
&#125;

TypeScriptTS 中类型功能一、类型推断
我们并不是必须编写显式类型注释，TS 类型系统会自动推断类型
当 TS 类型系统最终会推断出相同的类型时，最好不要添加类型注释

// 首次赋值为 string 之后，就不能在赋值 number 类型了
let str = "123";
str = 1; // 不能将类型“number”分配给类型“string”

二、上下文类型const names = ["Alice", "Bob", "Eve"];

names.forEach((s) => &#123;
  console.log(s.toUpperCase()); // 即使参数 s 没有类型注释，TS 也会自动推断出 s 的类型为 string
&#125;);

三、类型断言
适用于你比 Typescript 更加了解某个值的详情
把一个比较 宽泛 的类型转成一个更加 具体 的类型

// as 语法(推荐)
let someValue1: any = "this is a string";
// 相当于强制的把 any 类型转化为 string 类型，并且我明确的知道这个就是 string 类型的数值
let strLength1: number = (someValue1 as string).length;

// 尖括号语法(在 tsx 中会报错)
let someValue: any = "this is a string";
// 相当于强制的把 any 类型转化为 string 类型，两种形式是等价的.
let strLength: number = (&lt;string>someValue).length;

四、字面推断
当你使用对象初始化变量时，TypeScript 假定该对象的属性可能会在以后更改值

const obj = &#123; counter: 0 &#125;;
obj.counter = 1; // TS 不会假定 counter 属性是字面量 0

// req.method 被推断为 string，而不是 "GET"，因为 req.method 的值是可以进行更改的
declare function handleRequest(url: string, method: "GET" | "POST"): void;
const req = &#123; url: "https://example.com", method: "GET" &#125;;
handleRequest(req.url, req.method); // 类型“string”的参数不能赋给类型“"GET" | "POST"”的参数。

// 解决方案之一
// as const 后缀的作用类似于 const，但用于类型系统，确保为所有属性分配字面类型，而不是更通用的版本，如 string 或 number。
const req = &#123; url: "https://example.com", method: "GET" &#125; as const;

五、! 非空断言// ! 能够缩小 TS 的类型检查范围
// 这会告诉编辑器 x 不会是 undefined 或者 null
// 但是也仅仅是骗过了 TS 类型系统而已，如果 user 实际值为 undefined 则程序运行起来之后照样会报错
function liveDangerously(x?: number | null) &#123;
  console.log(x!.toFixed());
&#125;

六、类型收窄
类型收窄指 TypeScript 根据代码里的判断，把值的类型细化到比声明更具体的类型
typeof 检查、真值判断、相等判断、in 操作符和 instanceof 都可以作为类型守卫参与收窄

function logValue(x: Date | string) &#123;
  if (x instanceof Date) &#123;
    console.log(x.toUTCString());
  &#125; else &#123;
    console.log(x.toUpperCase());
  &#125;
&#125;


typeof null 在 JavaScript 里是 &quot;object&quot;，所以仅靠 typeof === &quot;object&quot; 不能把数组和 null 分开
联合类型的每个成员都带一个相同的字面量属性时，构成判别联合，判断这个属性就能收窄到对应成员

七、satisfies 操作符
satisfies 用来校验一个表达式的类型是否匹配某个类型，但不会改变这个表达式本身的结果类型
写成类型注解 : T 会把表达式拓宽成 T，丢失原本更精确的字面量推断；satisfies 只做校验，保留原推断类型

const palette = &#123;
  red: [255, 0, 0],
  green: "#00ff00",
&#125; satisfies Record&lt;string, string | number[]>;

