) &#123;
  isType["is" + type] = function (obj) &#123;
    return Object.prototype.toString.call(obj) === `[object $&#123;type&#125;]`;
  &#125;;
&#125;

三、高阶函数应用3.1 函数柯里化
柯里化又称为部分求值，是把接受多个参数的函数变成接受单一参数的函数

// 将传入的函数包装成 柯里化 的函数
// 本例的效果为实现 **延迟调用**
// currying 函数是不变的部分(通用函数)  callback 函数是变化的部分
function currying(callback) &#123;
  // 利用闭包的特性，将多次调用的参数全部存储到 args 数组中
  const args = [];
  return function () &#123;
    // 1. 当无传入参数时， 输出结果
    if (arguments.length === 0) &#123;
      return callback(args);
    &#125; else &#123;
      // 2. 当有参数传入时，将参数存储到闭包中，并再次返回当前函数等待下一次的调用
      args.push(...arguments);
      return arguments.callee;
    &#125;
  &#125;;
&#125;
// 具体的行为，将数组中的值求和
function cost(args) &#123;
  return args.reduce((total, item) => total + item);
&#125;

// 将 cost 函数包装成 柯里化 的函数
const Xcost = currying(cost);
// 经过柯里化的函数，单次调用不会运算出结果，只有当传入参数为空时才会将之前所有的调用整合到一起进行计算
Xcost(100);
Xcost(200);
Xcost(); // 300

3.2 防抖节流防抖（Debounce）概念：在事件被触发 n 秒后再执行回调，如果在这 n 秒内事件又被触发，则重新计时。
应用场景：搜索框输入、窗口大小调整、表单验证
/**
 * 防抖函数
 * @param &#123;Function&#125; func - 需要防抖的函数
 * @param &#123;Number&#125; delay - 延迟时间（毫秒）
 * @returns &#123;Function&#125; 防抖处理后的函数
 */
function debounce(func, delay) &#123;
  let timer = null;

  return function(...args) &#123;
    // 如果已有定时器，清除之前的定时器
    if (timer) &#123;
      clearTimeout(timer);
    &#125;

    // 设置新的定时器
    timer = setTimeout(() => &#123;
      func.apply(this, args);
    &#125;, delay);
  &#125;;
&#125;

节流（Throttle）概念：规定一个单位时间，在这个单位时间内，只能触发一次函数执行。如果这个单位时间内多次触发，只有一次生效。
应用场景：滚动加载、按钮点击、鼠标移动
/**
 * 节流函数
 * @param &#123;Function&#125; func - 需要节流的函数
 * @param &#123;Number&#125; delay - 时间间隔（毫秒）
 */
function throttle(func, delay) &#123;
  let timer = null;

  return function(...args) &#123;
    // 如果定时器存在，说明还在等待期，直接返回
    if (timer) return;

    // 设置定时器
    timer = setTimeout(() => &#123;
      func.apply(this, args);
      timer = null;
    &#125;, delay);
  &#125;;
&#125;

JavaScriptIterator(迭代器)
循环是迭代的基础，每次循环都会在下一次迭代开始之前完成，而每次迭代的顺序都是事先定义好的

for (let i = 1; i &lt;= 10; ++i) &#123;
  console.log(i);
&#125;

一、介绍
通用性：是为各种数据结构，提供一个统一的、简便的访问接口
有序性：是使得数据结构的成员能够按某种次序排列
ES6 创造了一种新的遍历命令 for…of 循环，Iterator 接口主要供 for…of 消费

// 一个对象如果要具备可被 for...of 循环调用的 Iterator 接口，就必须在 Symbol.iterator 的属性上部署遍历器生成方法(原型链上的对象具有该方法也可)
// 遍历器属性是一个方法
// 执行这个方法会返回一个对象，对象里面包含 next 方法
const obj = &#123;
  [Symbol.iterator]: function () &#123;
    return &#123;
      next: function () &#123;
        return &#123;
          value: 1,
          done: true,
        &#125;;
      &#125;,
    &#125;;
  &#125;,
&#125;;

二、Iterator 接口
原生具备 Iterator 接口的数据结构如下(!没有 Object)


Array
Map
Set
String
TypedArray
函数的 arguments 对象
NodeList 对象

// ES6 规定，默认的 Iterator 接口部署在数据结构的 Symbol.iterator 属性
// 可迭代对象
let arr = [1, 2, 3];
// 迭代器工厂函数
let iter = arr[Symbol.iterator];
// 迭代器
let iter = arr[Symbol.iterator]();
// 执行迭代
iter.next(); //&#123;value: 1, done: false&#125;
iter.next(); //&#123;value: 2, done: false&#125;
iter.next(); //&#123;value: 3, done: false&#125;

三、调用 Iterator 的场合
解构赋值
使用 … 扩展运算符
yield*
由于数组的遍历会调用遍历器接口，所以任何接受数组作为参数的场合，其实都调用了遍历器接口(例如: for...of Array.from() Map() Set() Promise.all() Promise.race())

四、几种遍历方法的对比4.1 for 循环
最原始的遍历方式，写起来比较麻烦(1. 需要单独记录索引 2. 需要使用特定语法([] 或 get())读值)
迭代中止: 可以使用 continue break 来终止循环

const arr = [1, 2, 3, 4, 5];
for (let i = 0; i &lt;= arr.length; i++) &#123;
  if (arr[i] == 4) &#123;
    break;
  &#125; else &#123;
    console.log(arr[i]); // 1 2 3
  &#125;
&#125;

4.2 forEach
与 for 对比，略有改善(1.不需要单独记录索引 2. 不需要使用特定语法([] 或 get())读值)
通用性受限：只能用于数组的数据类型
迭代中止受限：无法使用 continue break 来终止循环

const arr = [1, 2, 3, 4, 5];
arr.forEach((item, index) => &#123;
  console.log(item); // 1 2 3 4 5
&#125;);

4.3 for in
如果是数组和字符串的话，只能得到下标值，并不实用。只适合遍历对象
在遍历数组的过程中会访问到原型链上的数据
无序性: 对象的 key 是无序的，所以 for…in 遍历对象时并不能保证输出的顺序
迭代中止： 可以使用 break continue 来中止循环

// 输出原型上的数据
// 遍历数组时，得到的是下标值
const arr = ["a", "b", "c", "d"];
arr.__proto__.sss = "sss";
for (const key in arr) &#123;
  console.log(key); // 0 1 2 3 sss
&#125;

// 遍历对象时，为了避免原型上数据的干扰，一般都搭配 hasOwnProperty 使用
const obj = &#123;
  name: "foo",
  age: 18,
  sex: 0,
&#125;;
obj.__proto__.sss = "sss";

for (const key in obj) &#123;
  if (Object.hasOwnProperty.call(obj, key)) &#123;
    console.log(key); // name age sex
  &#125;
&#125;

4.4 for of
通用性: 任何实现了 Iterator 的数据结构都能使用此方法进行遍历
语法简洁: 1.不需要单独记录索引 2. 不需要使用特定语法([] 或 get())读值
迭代中止: 可以使用 break continue 来中止循环
有序性: 迭代元素的顺序是确定的
不会像 for…in 一样，访问原型上的数据

JavaScriptMap
JavaScript 的对象本质上是键值对的集合，但是传统上只能把字符串当做 key 值。
Map 类似于对象，也是键值对的集合，但是键的范围不限制于字符串，各种类型的值(包括对象)都可以当做键。

// 任何具有 Iterator 接口, 且每个成员都是一个双元素的数组的数据结构都可以当作 Map 构造函数的参数
const map = new Map([
  ['name', '张三'],
  ['title', 'Author']
]);
map // Map(2) &#123;'name' => '张三', 'title' => 'Author'&#125;

一、属性和方法1.1 size 属性
返回成员个数

const map = new Map([
  ["name", "张三"],
  ["title", "Author"],
]);
map.size; // 2

1.2 set
当键为引用类型时，判断键是否相等的依据是内存地址是否相等
当键为基本数据类型时，判断键是否相等 使用了 SameValueZero 相等性比较算法

// 因为 set 返回值为整个 map, 所以可以实现链式调用
map.set(key, value).set(key2, value2);

// SameValueZero 认为 NaN 和 NaN 相等， +0 和 -0 相等
const map = new Map();
const a = 0 / "", // NaN
  b = 0 / "", // NaN
  pz = +0,
  nz = -0;
a === b; // false
pz === nz; // true
map.set(a, "foo");
map.set(pz, "bar");
map.get(b); // foo
map.get(nz); // bar

1.3 get
读取数据

const objKey = &#123; name: "foo" &#125;;
const map = new Map([
  [objKey, "张三"],
  ["name", "李四"],
]);
map.get(objKey); // "张三"
map.get("name"); // "李四"
map.get(&#123; name: "foo" &#125;); // undefined

1.4 has 方法
是否存在某个键值
返回值: Boolean

const objKey = &#123; name: "foo" &#125;;
const map = new Map([
  [objKey, "张三"],
  ["name", "李四"],
]);
map.has(objKey); // true
map.has(&#123; name: "foo" &#125;); // false

1.5 delete 方法
