  const res1 = await getData("https://xxxxx/当前省/info");
  const res2 = await getData("https://xxxxx/当前市/info/?当前省=res1.Data");
  const res3 = await getData("https://xxxxx/当前区/info?当前市=res3.Data");
  return res3;
&#125;)()
  .then((res) => &#123;
    console.log("当前所属区域行政单位", res3.Data);
  &#125;)
  .catch((err) => &#123;
