                              "description": "真实人名"
                            &#125;
                          &#125;,
                          "required": ["ticketNumber", "name"]
                        &#125;
                        """)
                .build();
        ToolCallback toolCallback = MethodToolCallback.builder()
                .toolDefinition(
                        build)
                .toolMethod(method)
                .toolObject(toolService)
                .build();

        return List.of(toolCallback);
